import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"インストール","description":"F-DroidまたはGitHub ReleasesからPalleriaをインストールする方法。","frontmatter":{"title":"インストール","description":"F-DroidまたはGitHub ReleasesからPalleriaをインストールする方法。"},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1789107345000}'),r={name:"guide/install.md"};function s(o,e,d,n,p,c){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><p>PalleriaはF-Droidリポジトリ、またはGitHub Releasesから入手できます。自動更新を利用しやすいF-Droid経由がおすすめです。</p><h2 id="f-droidからインストール" tabindex="-1">F-Droidからインストール <a class="header-anchor" href="#f-droidからインストール" aria-label="Permalink to &quot;F-Droidからインストール&quot;">​</a></h2><p>次のリポジトリをF-Droidクライアントに追加します。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://yunfi.f5.si/Palleria/repo/</span></span></code></pre></div><p><a href="https://yunfi.f5.si/Palleria/repo?fingerprint=28A7F64F373AC1AD5FBB4822870E2E07B2B204C7EC71E58CE40F9D54EF2727D9" class="vp-button" target="_blank" rel="noreferrer">F-Droidにリポジトリを追加</a></p><ol><li>リンクをAndroid端末で開きます。</li><li>使用するF-Droidクライアントを選び、リポジトリを追加します。</li><li>リポジトリの更新が終わったら「Palleria」を検索します。</li><li>アプリを選択してインストールします。</li></ol><div class="tip custom-block"><p class="custom-block-title">リポジトリが表示されない場合</p><p>F-Droidの「リポジトリ」画面で、Palleria Dev Repositoryが有効になっているか確認し、手動で更新してください。</p></div><h2 id="github-releasesからインストール" tabindex="-1">GitHub Releasesからインストール <a class="header-anchor" href="#github-releasesからインストール" aria-label="Permalink to &quot;GitHub Releasesからインストール&quot;">​</a></h2><p><a href="https://github.com/yunfie-twitter/Palleria/releases/latest" target="_blank" rel="noreferrer">最新リリースを開く</a>からAPKをダウンロードします。</p><ol><li>最新リリースのAssetsからAPKファイルを選びます。</li><li>ダウンロードしたAPKを開きます。</li><li>Androidの案内に従い、必要な場合はブラウザまたはファイルアプリに「不明なアプリのインストール」を一時的に許可します。</li><li>インストール完了後、不要なら許可を戻します。</li></ol><div class="warning custom-block"><p class="custom-block-title">配布元を確認してください</p><p>APKはこのプロジェクトのGitHub Releasesまたは案内しているF-Droidリポジトリから取得してください。第三者が再配布するAPKの安全性は確認できません。</p></div><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><ul><li><strong>F-Droid版</strong>: F-Droidクライアントから更新できます。</li><li><strong>GitHub版</strong>: 新しいリリースのAPKをダウンロードし、上書きインストールします。</li></ul><p>同じ署名の正規APKであれば、通常は設定やアプリ内データを保持したまま更新できます。</p>',15)])])}const b=a(r,[["render",s]]);export{h as __pageData,b as default};
